def next_smallest_palindrome(n: int) -> int:
    # Convert the integer to a string to manipulate it
    n_str = str(n)
    length = len(n_str)

    # Handle single digit numbers
    if length == 1:
        return n + 1

    # Handle the case where the entire number needs to be mirrored
    if n_str == n_str[::-1] and n_str[0] == n_str[-1]:
        return int('1' + '0' * (length - 1) + '1')

    # Increment the middle digit(s) to find the next palindrome
    middle = length // 2
    if length % 2 == 0:
        left_half = n_str[:middle]
        new_left_half = str(int(left_half) + 1)
        if len(new_left_half) > middle:
            return int('1' + '0' * (length - 1) + '1')
        return int(new_left_half + new_left_half[::-1])
    else:
        left_half = n_str[:middle]
        middle_digit = n_str[middle]
        new_left_half = str(int(left_half + middle_digit) + 1)
        if len(new_left_half) > middle + 1:
            return int('1' + '0' * (length - 1) + '1')
        return int(new_left_half + new_left_half[-2::-1])

